#include "ui_icons.h"
#include <string.h>

static lv_image_dsc_t ui_make_img_dsc(const uint8_t *data, uint32_t data_size,
                                      uint16_t w, uint16_t h, uint8_t cf, uint16_t stride)
{
    lv_image_dsc_t dsc;
    memset(&dsc, 0, sizeof(dsc));
    dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
    dsc.header.cf = cf;
    dsc.header.flags = 0;
    dsc.header.w = w;
    dsc.header.h = h;
    dsc.header.stride = stride;
    dsc.data_size = data_size;
    dsc.data = data;
    return dsc;
}

static lv_image_dsc_t ui_make_rgb565_dsc(const uint8_t *data, uint32_t data_size,
                                         uint16_t w, uint16_t h)
{
    return ui_make_img_dsc(data, data_size, w, h, LV_COLOR_FORMAT_RGB565, (uint16_t)(w * 2));
}

static lv_image_dsc_t ui_make_argb8888_dsc(const uint8_t *data, uint32_t data_size,
                                           uint16_t w, uint16_t h)
{
    return ui_make_img_dsc(data, data_size, w, h, LV_COLOR_FORMAT_ARGB8888, (uint16_t)(w * 4));
}

#define UI_PLACEHOLDER_RGB565(name, W, H)                                      \
    static const uint8_t name##_map[(W) * (H) * 2] = {0};                      \
    const lv_image_dsc_t name = ui_make_rgb565_dsc(name##_map, sizeof(name##_map), (W), (H))

